  if (dataOk && !has('run_leak_and_bill_forecaster')) out.push('run_leak_and_bill_forecaster');
  if (!has('lookup_case_history')) out.push('lookup_case_history');
  if (!has('check_safety_guard')) out.push('check_safety_guard');
