    Object.keys(RANGE).forEach(f => { const v = r[f]; if (v !== undefined && v !== null && !(typeof v === 'number' && isFinite(v) && v >= RANGE[f][0] && v <= RANGE[f][1])) { if (c === r) c = Object.assign({}, r); c[f] = null; set_aside.push({ day: r.day, hour: r.hour, field: f, value: v }); } });
